"""Stable-slot COO path storage.

The tensor `alpha_{k,t,e}` is one when slot `t` of commodity `k` crosses edge
`e`.  Slots are *stable*: a case fixes the number of slots per commodity once
and forever, a slot is either `None` (a hole) or a concrete walk.  The COO
storage below therefore keeps one (edge, slot) entry per crossing and must
survive replacing a hole with a real path and back again, which the historical
implementation got wrong (it recomputed the arrays but threw the result away
and shifted slot indices).
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import List, Optional, Sequence, Tuple
import numpy as np
from array_utils.cpu.types import *
from array_utils.cpu.wrapper import *


@dataclass
class PathProvider:
    """COO path tensor with stable slot identities."""
    shape: Tuple[int, int, int]
    rows: List[IntegerCPUArray] = field(default_factory=list)
    cols: List[IntegerCPUArray] = field(default_factory=list)
    beta: IntegerCPUArray = field(default_factory=lambda: np.zeros(0, dtype=np.int32))
    slots: List[List[Optional[Tuple[int, ...]]]] = field(default_factory=list)

    # ------------------------------------------------------------------ build
    @staticmethod
    def from_slots(num_edges: int, slots: Sequence[Optional[Sequence[Optional[Sequence[int]]]]]) -> "PathProvider":
        K = len(slots)
        T = max([len(s) for s in slots], default=0)
        rows, cols, dense = [], [], []
        for k in range(K):
            edge_list, slot_list, row = [], [], []
            for t, path in enumerate(slots[k]):
                if path is None:
                    row.append(None)
                    continue
                row.append(tuple(int(e) for e in path))
                for e in row[-1]:
                    edge_list.append(e)
                    slot_list.append(t)
            dense.append(row)
            rows.append(np.asarray(edge_list, dtype=np.int32))
            cols.append(np.asarray(slot_list, dtype=np.int32))
        out = PathProvider(shape=(K, num_edges, T), rows=rows, cols=cols,
                           beta=np.full((K,), 0, dtype=np.int32), slots=dense)
        out.beta = np.asarray([len(s) for s in dense], dtype=np.int32)
        return out

    def __post_init__(self):
        K = self.shape[0]
        if len(self.rows) != K:
            self.rows = [np.zeros(0, dtype=np.int32) for _ in range(K)]
        if len(self.cols) != K:
            self.cols = [np.zeros(0, dtype=np.int32) for _ in range(K)]
        for k in range(K):
            self.rows[k] = np.asarray(self.rows[k], dtype=np.int32)
            self.cols[k] = np.asarray(self.cols[k], dtype=np.int32)
        self.beta = np.asarray(self.beta, dtype=np.int32)

    # ----------------------------------------------------------------- access
    @property
    def T(self) -> int:
        return self.shape[-1]

    @property
    def K(self) -> int:
        return self.shape[0]

    @property
    def N(self) -> int:
        return self.shape[1]

    def slot_count(self, k: int) -> int:
        return len(self.slots[k])

    def path(self, k: int, t: int) -> Optional[Tuple[int, ...]]:
        return self.slots[k][t]

    def entries(self, k: int, t: int) -> Tuple[np.ndarray, np.ndarray]:
        """Edges/slots of a single slot; empty arrays for a hole."""
        path = self.slots[k][t]
        if not path:
            return np.zeros(0, dtype=np.int32), np.zeros(0, dtype=np.int32)
        arr = np.asarray(path, dtype=np.int32)
        return arr, np.full(arr.shape, t, dtype=np.int32)

    def _rebuild(self, k: int) -> None:
        edges, slot_ids = [], []
        for t, path in enumerate(self.slots[k]):
            if path is None:
                continue
            for e in path:
                edges.append(e)
                slot_ids.append(t)
        self.rows[k] = np.asarray(edges, dtype=np.int32)
        self.cols[k] = np.asarray(slot_ids, dtype=np.int32)
        self.beta[k] = len(self.slots[k])
        self.shape = (len(self.slots), self.shape[1],
                      max([len(s) for s in self.slots], default=0))

    # ---------------------------------------------------------------- mutation
    def drop_path(self, k: int, t: int) -> None:
        """Make slot `t` of commodity `k` a hole; every other slot is untouched."""
        self.slots[k][t] = None
        self._rebuild(k)

    def update_path(self, k: int, t: int, path: Optional[Sequence[int]]) -> None:
        """Replace slot `t` in place.  Null slots leave a sparse hole behind."""
        self.slots[k][t] = None if path is None else tuple(int(e) for e in path)
        self._rebuild(k)

    # backwards compatible alias used by the event pipeline
    def set_path(self, k: int, t: int, path: Optional[Sequence[int]]) -> None:
        self.update_path(k, t, path)

    def add_path(self, k: int, path: Sequence[int], t: Optional[int] = None) -> None:
        """Fill the given (or the first empty) slot with `path`."""
        if t is None:
            for cand, existing in enumerate(self.slots[k]):
                if existing is None:
                    t = cand
                    break
        if t is None:
            raise ValueError('no free slot available')
        self.update_path(k, t, path)

    def reduce_max_path(self, new_T: int) -> None:
        """Shrink the slot window, dropping everything beyond `new_T`."""
        for k in range(len(self.slots)):
            self.slots[k] = self.slots[k][:new_T]
            self._rebuild(k)

    # ------------------------------------------------------------- predicates
    def is_available(self, k: int, t: int, capacities: np.ndarray) -> bool:
        path = self.slots[k][t]
        if not path:
            return False
        for e in path:
            if capacities[e] <= 0:
                return False
        return True

    def active_matrix(self, capacities: np.ndarray, demands: np.ndarray) -> np.ndarray:
        """`(T, K)` boolean mask of slots that may carry traffic."""
        T = self.T
        K = self.K
        out = np.zeros((max(T, 1), max(K, 1)), dtype=bool)
        for k in range(K):
            if demands[k] <= 0:
                continue
            for t in range(len(self.slots[k])):
                out[t, k] = self.is_available(k, t, capacities)
        return out[:T, :K] if T and K else out

    def as_array(self, k_start: int = 0, k_end: Optional[int] = None) -> BooleanCPUArray:
        """Dense `(K, N, T)` indicator tensor."""
        _, N, T = self.shape
        if k_end is None:
            K = self.shape[0]
        else:
            K = k_end - k_start
        out = cpu_bool_zeros((K, max(N, 1), max(T, 1)))
        for k in range(K):
            row = self.rows[k_start + k]
            col = self.cols[k_start + k]
            for i in range(len(row)):
                out[k, row[i], col[i]] = True
        return out

    def edge_lists(self, k: int) -> List[Optional[Tuple[int, ...]]]:
        return list(self.slots[k])

    def copy_slots(self) -> List[List[Optional[Tuple[int, ...]]]]:
        return [list(row) for row in self.slots]
